import sys


def kthRowPickSum(mat, k):
    m = len(mat)
    sys.setrecursionlimit(10000)
    rest = [0] * (m + 1)
    for i in range(m - 1, -1, -1):
        rest[i] = rest[i + 1] + mat[i][0]

    def count(S):
        cnt = 0

        def dfs(i, budget):
            nonlocal cnt
            if i == m:
                cnt += 1
                return
            for v in mat[i]:
                if v + rest[i + 1] > budget:
                    break
                dfs(i + 1, budget - v)
                if cnt >= k:
                    return

        dfs(0, S)
        return cnt

    lo, hi = rest[0], sum(row[-1] for row in mat)
    while lo < hi:
        mid = (lo + hi) // 2
        if count(mid) >= k:
            hi = mid
        else:
            lo = mid + 1
    return lo
